/**
 * The domain tree's product domains, in its order ("Product — what users
 * see"), then the ONE Industries menu, then the temporary Other holding pen.
 */
const DOMAIN_ORDER = [
  "Agents",
  "Applets",
  "Chat",
  "Workflows",
  "Intelligence",
  "Masterwork",
  "Knowledge",
  "Publish",
  "Media",
  "Workspace",
  "Communications",
  "CRM",
  "Marketing",
  "Human Resources",
  "Coding",
  "Integrations",
  "Account",
  "Industries",
  "Other",
] as const;

/**
 * Placeholders that knowingly borrow another destination's href until their
 * own page exists. Each is listed in common-docs/operations/conflicts.md.
 */
const PLACEHOLDER_HREF_TWINS = new Set(["Medical Hub (Soon)"]);

type Node = ShellNavItem | ShellNavChild;

function walk(nodes: readonly Node[], visit: (node: Node) => void): void {
  for (const node of nodes) {
    visit(node);
    if ("children" in node && node.children) walk(node.children, visit);
  }
}

function reachable<T>(pick: (node: Node) => T | undefined): Set<T> {
  const out = new Set<T>();
  walk(primaryNavItems, (node) => {
    const value = pick(node);
    if (value !== undefined) out.add(value);
  });
  return out;
}

function isDestination(node: Node): boolean {
  return !isNavActionChild(node as ShellNavChild) && !isNavPanelChild(node as ShellNavChild);
}

describe("main menu — nothing is lost", () => {
  it("still reaches every href the menu reached before the domain reorganization", () => {
    const hrefs = reachable((node) => node.href);
    const lost = HREFS_BEFORE_DOMAIN_TREE.filter((href) => !hrefs.has(href));
    expect(lost).toEqual([]);
  });

  it("still opens every window panel it opened before", () => {
    const panels = reachable((node) => ("panelAction" in node ? node.panelAction : undefined));
    const lost = PANEL_ACTIONS_BEFORE_DOMAIN_TREE.filter((id) => !panels.has(id as never));
    expect(lost).toEqual([]);
  });

  it("still offers every create action it offered before", () => {
    const actions = reachable((node) => ("action" in node ? node.action : undefined));
    const lost = CREATE_ACTIONS_BEFORE_DOMAIN_TREE.filter((id) => !actions.has(id as never));
    expect(lost).toEqual([]);
  });

  it("puts the domains in domain-tree order, then Industries, then Other", () => {
    expect(primaryNavItems.map((item) => item.label)).toEqual([...DOMAIN_ORDER]);
  });

  it("paints the Other holding pen with the attention tone", () => {
    const other = primaryNavItems.find((item) => item.label === "Other");
    expect(other?.tone).toBe("attention");
  });

  it("never lists one href twice at the same level", () => {
    const twins: string[] = [];
    const check = (nodes: readonly Node[], where: string) => {
      const seen = new Map<string, string>();
      for (const node of nodes.filter(isDestination)) {
        if (PLACEHOLDER_HREF_TWINS.has(node.label)) continue;
        const prior = seen.get(node.href);
        if (prior) twins.push(`${where}: ${prior} + ${node.label} → ${node.href}`);
        seen.set(node.href, node.label);
      }
    };
    check(primaryNavItems, "top level");
    for (const item of primaryNavItems) check(item.children ?? [], item.label);
    expect(twins).toEqual([]);
  });

  it("keeps each destination in exactly one domain (duplicates become one entry)", () => {
    const owners = new Map<string, string[]>();
    for (const item of primaryNavItems) {
      for (const child of (item.children ?? []).filter(isDestination)) {
        if (child.external || PLACEHOLDER_HREF_TWINS.has(child.label)) continue;
        owners.set(child.href, [...(owners.get(child.href) ?? []), item.label]);
      }
    }
    const shared = [...owners].filter(([, labels]) => labels.length > 1);
    expect(shared.map(([href, labels]) => `${href} → ${labels.join(", ")}`)).toEqual([]);
  });

  it("holds both Workflows doors — the run catalog and the external studio — in one Workflows", () => {
    const workflows = primaryNavItems.find((item) => item.label === "Workflows");
    const hrefs = (workflows?.children ?? []).map((child) => child.href);
    expect(hrefs).toContain("/workflows/all");
    expect(hrefs).toContain("https://workflows.aimatrx.com");
    expect(primaryNavItems.filter((item) => /workflow/i.test(item.label))).toHaveLength(1);
  });
});
